/*
    Fictional demo data: 14 service requests on real Zürich street trees (tree numbers
    from the open Baumkataster), created through the application workflow and dated
    over ~10 weeks. All names and e-mail addresses are invented (example.ch).
    Generated 2026-11-20 by _tools/export_seed.py.
    Run AFTER CreateTreeManagementZurich.sql. Does nothing if requests already exist.
*/
USE TreeManagementZurich;
GO

IF NOT EXISTS (SELECT 1 FROM dbo.TMZ_ServiceRequest)
BEGIN
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;
    SET IDENTITY_INSERT dbo.TMZ_ServiceRequest ON;
    SET IDENTITY_INSERT dbo.TMZ_ServiceRequest OFF;
    SET IDENTITY_INSERT dbo.TMZ_Inspection ON;
    SET IDENTITY_INSERT dbo.TMZ_Inspection OFF;
    SET IDENTITY_INSERT dbo.TMZ_WorkOrder ON;
    SET IDENTITY_INSERT dbo.TMZ_WorkOrder OFF;
    SET IDENTITY_INSERT dbo.TMZ_SrActivityPlan ON;
    SET IDENTITY_INSERT dbo.TMZ_SrActivityPlan OFF;
    SET IDENTITY_INSERT dbo.TMZ_Activity ON;
    SET IDENTITY_INSERT dbo.TMZ_Activity OFF;
    COMMIT TRANSACTION;
END
GO
